using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// --- 1. Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> ---
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Use it to serialize/deserialize with the typed overloads
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person roundTripped = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {roundTripped}");

// --- 2. Probe without throwing: TryGetTypeInfo ---
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded — kind: {found!.Kind}");
}

// Now probe for a type whose metadata might NOT be available.
// Use an options instance with no resolver at all:
var empty = new JsonSerializerOptions { TypeInfoResolver = null };
// Must mark as read-only (or serialize once) before querying
empty.MakeReadOnly();

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? notFound))
{
    Console.WriteLine("Unexpectedly found metadata!");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo(Person) on resolver-less options → false (no throw)");
}

// --- simple record used above ---
public record Person(string Name, int Age);

